<?php
/** Proof — the books' tools (surface: people and dimensions, the chart, the statements, the journal): each answers what the database says to the cent, as the asking member sees it. */
require __DIR__ . '/lib.php';
$W = p4world();
$BEA = 27; $CARL = 28; $VERA = 26; $OWNER = 1;
echo "1. People, dimensions, settings\n";
$d = tdata($BEA, 'find_members', ['q' => 'Carl', 'kind' => 'human']);
ok(count($d['members'] ?? []) === 1 && $d['members'][0]['member_id'] === 28 && $d['members'][0]['email'] === null, 'find_members: Carl by name; his address is not shown to Bea');
$d = tdata($CARL, 'find_members', ['q' => 'Carl', 'kind' => 'human']);
ok($d['members'][0]['email'] === 'carl@example.invalid', '...but Carl sees his own');
$pl = tdata($BEA, 'find_members', ['q' => 'Bookk']);
ok(in_array(['member_id' => 40, 'display_name' => 'SMOKE Bookkeeper'], $pl, true) && array_is_list($pl) && !array_filter($pl, fn ($r) => array_keys($r) !== ['member_id', 'display_name']), 'q alone answers a plain list (member_id, display_name)');
ok(count(tdata($BEA, 'find_members', ['kind' => 'agent'])['members']) >= 1 && count(array_filter(tdata($BEA, 'find_members', ['kind' => 'agent'])['members'], fn ($m) => $m['member_kind'] !== 'agent')) === 0, 'kind=agent lists agents only');
$d = tdata($BEA, 'find_departments', ['include_archived' => false]);
ok(isset($d['departments']) && count($d['departments']) === (int) val_as($BEA, 'SELECT count(*) FROM mcp_departments WHERE archived_at IS NULL'), 'find_departments: the live departments');
ok(is_array(tdata($BEA, 'find_sites', ['q' => 'zzzz'])) && tdata($BEA, 'find_sites', ['q' => 'zzzz']) === [], 'find_sites: a name nobody has resolves to an empty list');
$s = tdata($BEA, 'gl_settings');
ok($s['base_currency'] === 'USD' && $s['ar_account']['code'] === '1200' && $s['ap_account']['code'] === '2000' && $s['business_name'] === 'SMOKE Co' && isset($s['invoice_terms_days']), 'gl_settings: the base currency, the control accounts by code, the business name');
echo "2. The chart\n";
$d = tdata($BEA, 'find_accounts', ['q' => '6200']);
ok($d === [['account_id' => account_id('6200'), 'label' => '6200 — Software and subscriptions']], 'find_accounts q alone: a plain list with label "6200 — Software and subscriptions"');
$d = tdata($BEA, 'find_accounts', ['q' => 'software', 'limit' => 3]);
ok(count($d) >= 1 && $d[0]['label'] === '6200 — Software and subscriptions', 'a word of the name matches at the start of a word');
$d = tdata($BEA, 'find_accounts', ['q' => '1010', 'as_of' => '2026-12-31']);
$bank = tdata($BEA, 'find_accounts', ['account_type' => 'asset', 'is_bank' => true, 'as_of' => '2026-12-31']);
$b1010 = array_values(array_filter($bank['accounts'], fn ($a) => $a['code'] === '1010'))[0] ?? [];
ok(same_money($b1010['balance'] ?? 'x', val_as($BEA, 'SELECT gl_account_balance(:a, DATE \'2026-12-31\')', ['a' => account_id('1010')])) && count(array_filter($bank['accounts'], fn ($a) => !$a['is_bank'])) === 0, 'find_accounts: the bank flag filters, each account with its balance as of the date (1010: ' . ($b1010['balance'] ?? '?') . ')');
$ctl = tdata($BEA, 'find_accounts', ['is_control' => true, 'with_balance' => false]);
ok(array_column($ctl['accounts'], 'code') === ['1200', '2000'] && !isset($ctl['accounts'][0]['balance']), 'is_control: 1200 and 2000; with_balance=false leaves the balance out');
$byType = tdata($BEA, 'find_accounts', ['account_type' => 'income', 'limit' => 100]);
ok(count($byType['accounts']) === (int) val_as($BEA, "SELECT count(*) FROM mcp_accounts WHERE account_type = 'income' AND archived_at IS NULL") && !has_key($byType, 'nothing'), 'the type filter counts what the view holds');
ok(same_money(tdata($BEA, 'account_balance', ['code' => '1010', 'as_of' => '2026-12-31'])['balance'], $b1010['balance']), 'account_balance by code equals find_accounts');
$ab = tdata($BEA, 'account_balance', ['account_id' => account_id('6200'), 'as_of' => '2026-12-31']);
ok($ab['code'] === '6200' && $ab['normal_balance'] === 'debit' && same_money($ab['balance'], val_as($BEA, 'SELECT gl_account_balance(:a, DATE \'2026-12-31\')', ['a' => account_id('6200')])), 'account_balance by id: the normal sense (an expense in debits)');
ok(tool($BEA, 'account_balance', ['code' => '9999'])['error'], 'an unknown account is a refusal in words');
$act = tdata($BEA, 'account_activity', ['code' => '1010', 'from' => '2026-01-01', 'to' => '2026-12-31']);
ok($act['count'] === count($act['lines']) && $act['count'] >= 3 && same_money(end($act['lines'])['running_balance'], tdata($BEA, 'account_balance', ['code' => '1010', 'as_of' => '2026-12-31'])['balance']), 'account_activity: the lines in order, the last running balance equals the account\'s balance (' . $act['count'] . ' lines)');
ok(count(tdata($BEA, 'account_activity', ['code' => '1010', 'from' => '2026-01-01', 'to' => '2026-01-31'])['lines']) === 1, 'a narrower period holds only January\'s line (the owner\'s capital)');
$pr = tdata($BEA, 'posting_rules', []);
ok(count($pr['rules']) === (int) val_as($BEA, 'SELECT count(*) FROM mcp_posting_rules') && count(tdata($BEA, 'posting_rules', ['source' => 'invoice'])['rules']) >= 1, 'posting_rules: every rule, or one source\'s');
$p = tdata($BEA, 'find_periods', ['q' => '2026-02']);
ok(count($p) === 1 && $p[0]['name'] === '2026-02', 'find_periods q alone: a plain list (fiscal_period_id, name)');
$p = tdata($BEA, 'find_periods', ['q' => '2026-02', 'status' => 'open']);
$feb = $p['periods'][0] ?? [];
ok(($feb['reopen_count'] ?? 0) === 1 && $feb['reopen_reason'] === 'SMOKE: a late vendor bill' && $feb['reopened_by_name'] === 'SMOKE Carl' && $feb['posted_entries'] >= 2, 'February: reopened once by Carl, with the reason and its posted count');
ok(tdata($BEA, 'find_periods', ['date' => '2026-09-15'])['periods'][0]['name'] === '2026-09' && count(tdata($BEA, 'find_periods', [])['fiscal_years']) === 1, 'the period a date falls in; the fiscal years come with it');
ok(tdata($BEA, 'find_periods', ['q' => 'FY2026'])[0]['fiscal_year_name'] === 'FY2026', 'q "FY2026" resolves the year (fiscal_year_id, fiscal_year_name)');
echo "3. The statements\n";
$tb = tdata($BEA, 'trial_balance', ['as_of' => '2026-12-31']);
ok($tb['balanced'] === true && same_money($tb['total_debit'], $tb['total_credit']) && same_money($tb['total_debit'], val_as($BEA, 'SELECT sum(debit) FROM gl_trial_balance(DATE \'2026-12-31\')')) && count($tb['rows']) === (int) val_as($BEA, 'SELECT count(*) FROM gl_trial_balance(DATE \'2026-12-31\')'), 'trial_balance: balanced, the totals and rows equal the function\'s');
$pl = tdata($BEA, 'profit_and_loss', ['period' => '2026-03']);
ok($pl['from'] === '2026-03-01' && $pl['to'] === '2026-03-31' && same_money($pl['net_income'], val_as($BEA, "SELECT gl_net_income('2026-03-01', '2026-03-31')")) && same_money($pl['net_income'], (float) $pl['total_income'] - (float) $pl['total_expenses']), 'profit_and_loss for 2026-03: net income equals gl_net_income() and income less expenses (' . $pl['net_income'] . ')');
$pl = tdata($BEA, 'profit_and_loss', ['period' => 'FY2026', 'department_id' => 0]);
$plAll = tdata($BEA, 'profit_and_loss', ['period' => 'FY2026']);
ok(same_money($plAll['net_income'], val_as($BEA, "SELECT gl_net_income('2026-01-01', '2026-12-31')")) && count($plAll['income']) >= 1, 'FY2026 resolves to the year (' . $plAll['from'] . ' to ' . $plAll['to'] . ')');
$cmp = tdata($BEA, 'profit_and_loss', ['from' => '2026-04-01', 'to' => '2026-04-30', 'compare' => 'previous']);
ok($cmp['prior']['from'] === '2026-03-01' && $cmp['prior']['to'] === '2026-03-31' && isset($cmp['net_variance']['variance']) && count(array_filter($cmp['expenses'], fn ($a) => array_key_exists('variance', $a))) === count($cmp['expenses']), 'compare=previous: the month before, a variance on every account and on net income');
$cy = tdata($BEA, 'profit_and_loss', ['from' => '2026-04-01', 'to' => '2026-04-30', 'compare' => 'last_year']);
ok($cy['prior']['from'] === '2025-04-01' && $cy['prior']['to'] === '2025-04-30', 'compare=last_year: the same dates a year earlier');
ok(tool($BEA, 'profit_and_loss', ['period' => 'nonsense'])['error'], 'an unknown period is refused in words');
$bs = tdata($BEA, 'balance_sheet', ['as_of' => '2026-12-31']);
ok((float) $bs['check']['difference'] === 0.0 && count($bs['sections']) >= 2, 'balance_sheet: the equation holds (difference 0), sections: ' . implode(', ', array_column($bs['sections'], 'section')));
$bs2 = tdata($BEA, 'balance_sheet', ['as_of' => '2026-12-31', 'compare' => 'last_year']);
ok($bs2['compare_as_of'] === '2025-12-31' && array_key_exists('prior', $bs2['sections'][0]['rows'][0] ?? ['prior' => 0]), 'compare adds a prior column');
$cf = tdata($BEA, 'cash_flow', ['period' => 'FY2026']);
ok(count($cf['sections']) >= 1 && array_sum(array_map(fn ($s) => count($s['lines']), $cf['sections'])) === (int) val_as($BEA, "SELECT count(*) FROM gl_cash_flow('2026-01-01', '2026-12-31')"), 'cash_flow: every line of the function, in sections');
$cc = tdata($BEA, 'control_check', ['as_of' => '2026-10-05']);
$rcv = array_values(array_filter($cc['controls'], fn ($c) => $c['control'] === 'receivable'))[0]; $pay = array_values(array_filter($cc['controls'], fn ($c) => $c['control'] === 'payable'))[0];
$unapplied = (float) val_as($BEA, "SELECT COALESCE(sum(unapplied), 0) FROM mcp_receipts WHERE status = 'recorded'") + (float) val_as($BEA, "SELECT COALESCE(sum(balance), 0) FROM mcp_credit_notes WHERE status = 'issued'");
ok(count($cc['controls']) === 2 && same_money($pay['difference'], '0.00') && same_money($rcv['difference'], $unapplied) && $unapplied > 0 && $cc['ties'] === false, 'control_check: payables tie; receivables differ by exactly the unapplied receipt and credit (' . $rcv['difference'] . ') — the ledger carries them, the invoices do not yet');
echo "4. The journal\n";
$feb = (string) one('SELECT number FROM journal_entries WHERE id = :i', ['i' => $W['feb']]);
$d = tdata($BEA, 'find_journal_entries', ['q' => $feb]);
ok($d === [['journal_entry_id' => $W['feb'], 'label' => $feb . ' — SMOKE February software']], 'find_journal_entries q alone: a number matches whole; the list is (journal_entry_id, label)');
$d = tdata($BEA, 'find_journal_entries', ['q' => 'February']);
ok(count($d) === 2, 'words of the memo match at the start of a word (two February entries): ' . count($d));
$d = tdata($BEA, 'find_journal_entries', ['status' => ['draft']]);
ok(count($d['entries']) === 1 && $d['entries'][0]['journal_entry_id'] === $W['draft'] && $d['entries'][0]['number'] === null, 'status=draft lists the draft (no number yet)');
$d = tdata($BEA, 'find_journal_entries', ['source' => ['reversal']]);
ok(count($d['entries']) === 1 && $d['entries'][0]['reversal_of_number'] !== null, 'source=reversal: the reversing entry names what it reverses');
$d = tdata($BEA, 'find_journal_entries', ['account_id' => account_id('3000')]);
ok(count($d['entries']) === 1 && $d['entries'][0]['journal_entry_id'] === $W['capital'], 'account_id: the entries with a line on 3000');
$d = tdata($BEA, 'find_journal_entries', ['from' => '2026-02-01', 'to' => '2026-02-28', 'status' => ['posted', 'reversed']]);
ok(count($d['entries']) === 2 && $d['entries'][0]['period_name'] === '2026-02', 'a date range and a status list');
$d = tdata($BEA, 'find_journal_entries', ['source_type' => 'invoice', 'source_id' => $W['inv_a1']]);
ok(count($d['entries']) === 1 && $d['entries'][0]['source'] === 'invoice', 'by source document: the entry an invoice posted');
$g = tdata($BEA, 'get_journal_entry', ['number' => $feb]);
ok(count($g['lines']) === 2 && $g['entry']['status'] === 'posted' && same_money($g['entry']['total_debit'], '100.00') && $g['lines'][0]['account_code'] === '6200' && $g['source_document'] === null, 'get_journal_entry by number: head, two lines, no source document (a manual entry)');
$gi = tdata($BEA, 'get_journal_entry', ['journal_entry_id' => (int) one('SELECT journal_entry_id FROM invoices WHERE id = :i', ['i' => $W['inv_a1']])]);
ok(($gi['source_document']['type'] ?? '') === 'invoice' && str_starts_with((string) $gi['source_document']['number'], 'INV-'), 'an invoice\'s entry names its source document (invoice, INV-…)');
$wr = tdata($BEA, 'get_journal_entry', ['journal_entry_id' => $W['wrong']]);
ok($wr['entry']['status'] === 'reversed' && $wr['entry']['reversed_by_number'] !== null && $wr['entry']['reversal_reason'] === null || $wr['entry']['reversed_by_number'] !== null, 'a reversed entry names its reversal');
ok(tool($BEA, 'get_journal_entry', ['number' => 'JE-999999'])['error'] && tool($BEA, 'get_journal_entry', [])['error'], 'an unknown entry and a call with neither id nor number are refusals');
$un = tdata($BEA, 'unposted_entries', ['detail' => true]);
$sum = sql_as($BEA, 'SELECT * FROM gl_unposted_summary()')[0];
ok($un['waiting']['draft_entries'] === $sum['draft_entries'] && $un['waiting']['draft_bills'] === $sum['draft_bills'] && $un['waiting']['open_claims'] === $sum['open_claims'] && $un['posted_through'] === val_as($BEA, 'SELECT gl_posted_through()'), 'unposted_entries: the counts equal gl_unposted_summary() and the posted-through date');
ok(count($un['draft_entries']) === 1 && $un['draft_entries'][0]['balanced'] === true && $un['draft_entries'][0]['period_status'] === 'open' && same_money($un['draft_entries'][0]['total_debit'], '20.00'), 'detail lists the draft entry: balanced, its period open, 20.00');
ok(!isset(tdata($BEA, 'unposted_entries', [])['draft_entries']), 'without detail only the counts');
echo "5. What each role sees\n";
$cv = tdata($VERA, 'find_customers', ['include_archived' => false]);
$cb = tdata($BEA, 'find_customers', ['include_archived' => false]);
ok(count($cv['customers']) === count($cb['customers']) && $cv['customers'][0]['email'] === null && $cb['customers'][0]['email'] !== null, 'a Viewer sees every customer by name and balance but no contact details; the Bookkeeper sees both');
ok(tdata($VERA, 'trial_balance', ['as_of' => '2026-12-31'])['balanced'] === true, 'a Viewer reads the statements (reports.view)');
echo "6. records_search\n";
$r = tdata($BEA, 'records_search', ['sql' => "SELECT number, total, status FROM mcp_invoices WHERE invoice_id = {$W['inv_a1']}"]);
ok(count($r) === 1 && $r[0]['total'] === '1082.50' && is_string($r[0]['total']), 'a SELECT over the views answers; money is a string with its scale ("1082.50")');
ok(count(tdata($BEA, 'records_search', ['sql' => 'SELECT * FROM gl_trial_balance(CURRENT_DATE)'])) >= 3, 'the statement functions are readable from it');
foreach (['INSERT INTO accounts (code) VALUES (1)' => 'Only a single SELECT', 'SELECT 1; SELECT 2' => 'Only one statement', "SELECT set_config('app.member_id', '1', false)" => 'not available', 'SELECT gl_invoice_issue(1, 1)' => 'not available', 'SELECT * FROM gl_share_ar_aging(CURRENT_DATE)' => 'not available', 'SELECT pg_sleep(1)' => 'not available', 'SELECT next_document_number(1)' => 'not available', "SELECT mcp_resolve_token('x', 'mcp')" => 'not available'] as $sql => $why) {
    $c = tool($BEA, 'records_search', ['sql' => $sql]);
    ok($c['error'] && str_contains($c['text'], $why), 'refused: ' . substr($sql, 0, 48));
}
ok(tool($BEA, 'records_search', ['sql' => 'SELECT * FROM accounts'])['error'], 'a base table is not readable by the read role');
ok(count(tdata($BEA, 'records_search', ['sql' => 'SELECT generate_series(1, 500) AS n'])) === 200, 'at most 200 rows');
finish();
